package main

import (
	"regexp"
	"strconv"
	"strings"
)

var intRe = regexp.MustCompile(`^-?[0-9]{1,18}$`)

func badArg(line int, name string) { fail(line, "type error: bad argument to "+name) }

func installBuiltins(it *Interp) {
	reg := func(name string, arity []int, fn func(it *Interp, line int, a []Value) Value) {
		for _, b := range BUILTINS {
			if b == name {
				it.globals.vars[name] = &Builtin{Name: name, Arity: arity, Fn: fn}
			}
		}
	}
	reg("len", []int{1}, func(it *Interp, line int, a []Value) Value {
		switch x := a[0].(type) {
		case string:
			return int64(len(x))
		case []Value:
			return int64(len(x))
		}
		badArg(line, "len")
		return nil
	})
	reg("str", []int{1}, func(it *Interp, line int, a []Value) Value { return show(a[0], false) })
	reg("int", []int{1}, func(it *Interp, line int, a []Value) Value {
		switch x := a[0].(type) {
		case int64:
			return x
		case string:
			if intRe.MatchString(x) {
				v, _ := strconv.ParseInt(x, 10, 64)
				return v
			}
			fail(line, "cannot convert '"+x+"' to int")
		}
		badArg(line, "int")
		return nil
	})
	reg("push", []int{2}, func(it *Interp, line int, a []Value) Value {
		xs, ok := a[0].([]Value)
		if !ok {
			badArg(line, "push")
		}
		out := make([]Value, 0, len(xs)+1)
		out = append(out, xs...)
		return append(out, a[1])
	})
	reg("range", []int{1, 2}, func(it *Interp, line int, a []Value) Value {
		var nums []int64
		for _, x := range a {
			v, ok := x.(int64)
			if !ok {
				badArg(line, "range")
			}
			nums = append(nums, v)
		}
		lo, hi := int64(0), nums[0]
		if len(nums) == 2 {
			lo, hi = nums[0], nums[1]
		}
		if hi-lo > 10000 {
			fail(line, "range too large")
		}
		out := []Value{}
		for v := lo; v < hi; v++ {
			out = append(out, v)
		}
		return out
	})
	reg("map", []int{2}, func(it *Interp, line int, a []Value) Value {
		xs, ok := a[0].([]Value)
		if !ok {
			badArg(line, "map")
		}
		out := make([]Value, 0, len(xs))
		for _, x := range xs {
			out = append(out, it.call(a[1], []Value{x}, line))
		}
		return out
	})
	reg("filter", []int{2}, func(it *Interp, line int, a []Value) Value {
		xs, ok := a[0].([]Value)
		if !ok {
			badArg(line, "filter")
		}
		out := []Value{}
		for _, x := range xs {
			if truthy(it.call(a[1], []Value{x}, line)) {
				out = append(out, x)
			}
		}
		return out
	})
	reg("fold", []int{3}, func(it *Interp, line int, a []Value) Value {
		xs, ok := a[0].([]Value)
		if !ok {
			badArg(line, "fold")
		}
		acc := a[1]
		for _, x := range xs {
			acc = it.call(a[2], []Value{acc, x}, line)
		}
		return acc
	})
	reg("join", []int{2}, func(it *Interp, line int, a []Value) Value {
		xs, ok := a[0].([]Value)
		sep, ok2 := a[1].(string)
		if !ok || !ok2 {
			badArg(line, "join")
		}
		parts := make([]string, len(xs))
		for i, x := range xs {
			parts[i] = show(x, false)
		}
		return strings.Join(parts, sep)
	})
	reg("split", []int{2}, func(it *Interp, line int, a []Value) Value {
		s, ok := a[0].(string)
		sep, ok2 := a[1].(string)
		if !ok || !ok2 || sep == "" {
			badArg(line, "split")
		}
		out := []Value{}
		for _, p := range strings.Split(s, sep) {
			out = append(out, p)
		}
		return out
	})
	reg("upper", []int{1}, func(it *Interp, line int, a []Value) Value {
		s, ok := a[0].(string)
		if !ok {
			badArg(line, "upper")
		}
		b := []byte(s)
		for i, c := range b {
			if c >= 'a' && c <= 'z' {
				b[i] = c - 32
			}
		}
		return string(b)
	})
	reg("slice", []int{3}, func(it *Interp, line int, a []Value) Value {
		lo, ok1 := a[1].(int64)
		hi, ok2 := a[2].(int64)
		if !ok1 || !ok2 {
			badArg(line, "slice")
		}
		clamp := func(v, n int64) int64 {
			if v < 0 {
				return 0
			}
			if v > n {
				return n
			}
			return v
		}
		switch x := a[0].(type) {
		case string:
			l, h := clamp(lo, int64(len(x))), clamp(hi, int64(len(x)))
			if l >= h {
				return ""
			}
			return x[l:h]
		case []Value:
			l, h := clamp(lo, int64(len(x))), clamp(hi, int64(len(x)))
			if l >= h {
				return []Value{}
			}
			out := make([]Value, h-l)
			copy(out, x[l:h])
			return out
		}
		badArg(line, "slice")
		return nil
	})
}

solution.interp.go:
package main

import (
	"fmt"
	"math"
)

type returnSignal struct{ v Value }

// Env is a scope.
type Env struct {
	vars   map[string]Value
	parent *Env
}

func newEnv(parent *Env) *Env { return &Env{vars: map[string]Value{}, parent: parent} }

func (e *Env) find(name string) *Env {
	for s := e; s != nil; s = s.parent {
		if _, ok := s.vars[name]; ok {
			return s
		}
	}
	return nil
}

type handlerFrame struct {
	tag string
	fn  Value
}

// Interp evaluates a program.
type Interp struct {
	out      []string
	depth    int
	steps    int
	handlers []handlerFrame
	fnDepth  int
	globals  *Env
}

func newInterp() *Interp {
	it := &Interp{globals: newEnv(nil)}
	installBuiltins(it)
	return it
}

func checked(line int, ok bool) {
	if !ok {
		fail(line, "integer overflow")
	}
}

func (it *Interp) call(f Value, args []Value, line int) Value {
	switch fn := f.(type) {
	case *Closure:
		return it.callClosure(fn, args, line)
	case *Builtin:
		okCount := false
		for _, a := range fn.Arity {
			if a == len(args) {
				okCount = true
			}
		}
		if !okCount {
			exp := ""
			for i, a := range fn.Arity {
				if i > 0 {
					exp += " or "
				}
				exp += fmt.Sprint(a)
			}
			fail(line, fmt.Sprintf("wrong number of arguments for %s: expected %s, got %d", fn.Name, exp, len(args)))
		}
		return fn.Fn(it, line, args)
	}
	fail(line, "type error: "+typeName(f)+" is not callable")
	return nil
}

func (it *Interp) callClosure(f *Closure, args []Value, line int) (result Value) {
	if len(args) != len(f.Params) {
		name := f.Name
		if name == "" {
			name = "function"
		}
		fail(line, fmt.Sprintf("wrong number of arguments for %s: expected %d, got %d", name, len(f.Params), len(args)))
	}
	if it.depth >= DEPTH_LIMIT {
		fail(line, "call depth exceeded")
	}
	env := newEnv(f.Env)
	for i, p := range f.Params {
		env.vars[p] = args[i]
	}
	it.depth++
	it.fnDepth++
	defer func() {
		it.depth--
		it.fnDepth--
		if r := recover(); r != nil {
			if rs, ok := r.(returnSignal); ok {
				result = rs.v
				return
			}
			panic(r)
		}
	}()
	return it.eval(f.Body, env)
}

// runBlock runs statements in a new scope; the value is that of the last statement. Deferred statements run at exit.
func (it *Interp) runBlock(stmts []*Node, env *Env, scope bool) Value {
	inner := env
	if scope {
		inner = newEnv(env)
	}
	var deferred []*Node
	var value Value
	func() {
		defer func() {
			if r := recover(); r != nil {
				if _, ok := r.(returnSignal); ok {
					it.runDeferred(&deferred, inner)
				}
				panic(r)
			}
		}()
		for _, st := range stmts {
			value = it.exec(st, inner, &deferred)
		}
	}()
	it.runDeferred(&deferred, inner)
	return value
}

func (it *Interp) runDeferred(deferred *[]*Node, env *Env) {
	for len(*deferred) > 0 {
		last := len(*deferred) - 1
		stmt := (*deferred)[last]
		*deferred = (*deferred)[:last]
		var later []*Node
		it.exec(stmt, env, &later)
		it.runDeferred(&later, env)
	}
}

func (it *Interp) tick(line int) {
	it.steps++
	if it.steps > LOOP_LIMIT {
		fail(line, "step limit exceeded")
	}
}

func (it *Interp) exec(st *Node, env *Env, deferred *[]*Node) Value {
	switch st.Kind {
	case "expr":
		return it.eval(st.A, env)
	case "let":
		env.vars[st.Name] = it.eval(st.A, env)
	case "fndef":
		env.vars[st.Name] = &Closure{Name: st.Name, Params: st.Params, Body: st.A, Env: env}
	case "assign":
		v := it.eval(st.A, env)
		e := env.find(st.Name)
		if e == nil {
			fail(st.Line, "cannot assign to unbound variable '"+st.Name+"'")
		}
		e.vars[st.Name] = v
	case "print":
		it.out = append(it.out, show(it.eval(st.A, env), false))
	case "return":
		if it.fnDepth == 0 {
			fail(st.Line, "return outside function")
		}
		var v Value
		if st.A != nil {
			v = it.eval(st.A, env)
		}
		panic(returnSignal{v})
	case "defer":
		*deferred = append(*deferred, st.A)
	case "while":
		for truthy(it.eval(st.A, env)) {
			it.tick(st.Line)
			it.runBlock(st.Body, env, true)
		}
	case "for":
		seq := it.eval(st.A, env)
		var items []Value
		switch s := seq.(type) {
		case string:
			for i := 0; i < len(s); i++ {
				items = append(items, string(s[i]))
			}
		case []Value:
			items = append(items, s...)
		default:
			fail(st.Line, "type error: cannot iterate over "+typeName(seq))
		}
		for _, item := range items {
			it.tick(st.Line)
			inner := newEnv(env)
			inner.vars[st.Name] = item
			it.runBlock(st.Body, inner, true)
		}
	default:
		panic("unknown statement " + st.Kind)
	}
	return nil
}

func (it *Interp) eval(n *Node, env *Env) Value {
	switch n.Kind {
	case "lit":
		return n.Val
	case "var":
		e := env.find(n.Name)
		if e == nil {
			fail(n.Line, "unbound variable '"+n.Name+"'")
		}
		return e.vars[n.Name]
	case "bin":
		return it.binary(n, env)
	case "call":
		f := it.eval(n.A, env)
		args := make([]Value, len(n.List))
		for i, a := range n.List {
			args[i] = it.eval(a, env)
		}
		return it.call(f, args, n.Line)
	case "pipe":
		left := it.eval(n.A, env)
		right := n.B
		var f Value
		args := []Value{left}
		if right.Kind == "call" {
			f = it.eval(right.A, env)
			for _, a := range right.List {
				args = append(args, it.eval(a, env))
			}
		} else {
			f = it.eval(right, env)
		}
		return it.call(f, args, n.Line)
	case "if":
		if truthy(it.eval(n.A, env)) {
			return it.runBlock(n.Body, env, true)
		}
		if n.HasElse {
			return it.runBlock(n.Else, env, true)
		}
		return nil
	case "do":
		return it.runBlock(n.Body, env, true)
	case "lambda":
		return &Closure{Params: n.Params, Body: n.A, Env: env}
	case "list":
		items := make([]Value, len(n.List))
		for i, x := range n.List {
			items[i] = it.eval(x, env)
		}
		return items
	case "index":
		return it.index(n, env)
	case "and":
		left := it.eval(n.A, env)
		if truthy(left) {
			return it.eval(n.B, env)
		}
		return left
	case "or":
		left := it.eval(n.A, env)
		if truthy(left) {
			return left
		}
		return it.eval(n.B, env)
	case "not":
		return !truthy(it.eval(n.A, env))
	case "neg":
		v := it.eval(n.A, env)
		x, ok := v.(int64)
		if !ok {
			fail(n.Line, "type error: cannot apply '-' to "+typeName(v))
		}
		checked(n.Line, x != math.MinInt64)
		return -x
	case "emit":
		return it.evalEmit(n, env)
	case "handle":
		return it.evalHandle(n, env)
	}
	panic("unknown expression " + n.Kind)
}

func (it *Interp) evalEmit(n *Node, env *Env) Value {
	value := it.eval(n.A, env)
	idx := -1
	for i := len(it.handlers) - 1; i >= 0; i-- {
		if it.handlers[i].tag == n.Name {
			idx = i
			break
		}
	}
	if idx < 0 {
		fail(n.Line, "unhandled emit '"+n.Name+"'")
	}
	handler := it.handlers[idx].fn
	saved := it.handlers
	it.handlers = saved[:idx]
	defer func() { it.handlers = saved }()
	return it.call(handler, []Value{value}, n.Line)
}

func (it *Interp) evalHandle(n *Node, env *Env) Value {
	h := it.eval(n.A, env)
	switch h.(type) {
	case *Closure, *Builtin:
	default:
		fail(n.Line, "type error: "+typeName(h)+" is not callable")
	}
	nh := make([]handlerFrame, len(it.handlers)+1)
	copy(nh, it.handlers)
	nh[len(it.handlers)] = handlerFrame{tag: n.Name, fn: h}
	it.handlers = nh
	depth := len(nh)
	defer func() { it.handlers = it.handlers[:depth-1] }()
	return it.runBlock(n.Body, env, true)
}

func (it *Interp) binary(n *Node, env *Env) Value {
	op := n.Name
	a := it.eval(n.A, env)
	b := it.eval(n.B, env)
	ta, tb := typeName(a), typeName(b)
	switch op {
	case "==":
		return equal(a, b)
	case "!=":
		return !equal(a, b)
	case "<", "<=", ">", ">=":
		if ta == tb && ta == "int" {
			x, y := a.(int64), b.(int64)
			switch op {
			case "<":
				return x < y
			case "<=":
				return x <= y
			case ">":
				return x > y
			}
			return x >= y
		}
		if ta == tb && ta == "string" {
			x, y := a.(string), b.(string)
			switch op {
			case "<":
				return x < y
			case "<=":
				return x <= y
			case ">":
				return x > y
			}
			return x >= y
		}
	case "+":
		if ta == "int" && tb == "int" {
			x, y := a.(int64), b.(int64)
			c := x + y
			checked(n.Line, !((x > 0 && y > 0 && c < 0) || (x < 0 && y < 0 && c >= 0)))
			return c
		}
		if ta == tb && ta == "string" {
			return a.(string) + b.(string)
		}
		if ta == tb && ta == "list" {
			x, y := a.([]Value), b.([]Value)
			out := make([]Value, 0, len(x)+len(y))
			out = append(out, x...)
			return append(out, y...)
		}
	default:
		if ta == "int" && tb == "int" {
			x, y := a.(int64), b.(int64)
			switch op {
			case "-":
				c := x - y
				checked(n.Line, !((x >= 0 && y < 0 && c < 0) || (x < 0 && y > 0 && c >= 0)))
				return c
			case "*":
				c := x * y
				checked(n.Line, x == 0 || (c/x == y && !(x == -1 && y == math.MinInt64)))
				return c
			}
			if y == 0 {
				fail(n.Line, "division by zero")
			}
			if op == "/" {
				checked(n.Line, !(x == math.MinInt64 && y == -1))
				return x / y
			}
			if y == -1 {
				return int64(0)
			}
			return x % y
		}
	}
	fail(n.Line, fmt.Sprintf("type error: cannot apply '%s' to %s and %s", op, ta, tb))
	return nil
}

func (it *Interp) index(n *Node, env *Env) Value {
	seq := it.eval(n.A, env)
	iv := it.eval(n.B, env)
	ts, ti := typeName(seq), typeName(iv)
	if (ts != "list" && ts != "string") || ti != "int" {
		fail(n.Line, fmt.Sprintf("type error: cannot index %s with %s", ts, ti))
	}
	i := iv.(int64)
	var ln int64
	if s, ok := seq.(string); ok {
		ln = int64(len(s))
	} else {
		ln = int64(len(seq.([]Value)))
	}
	j := i
	if i < 0 {
		j = i + ln
	}
	if j < 0 || j >= ln {
		fail(n.Line, fmt.Sprintf("index out of range: %d (length %d)", i, ln))
	}
	if s, ok := seq.(string); ok {
		return string(s[j])
	}
	return seq.([]Value)[j]
}

solution.lexer.go:
package main

import (
	"fmt"
	"strconv"
)

// FableError is a parse or runtime error at a line.
type FableError struct {
	Line int
	Msg  string
}

func fail(line int, msg string) {
	panic(&FableError{Line: line, Msg: msg})
}

// Tok is a token: kind is int, str, id, kw, op, nl or eof.
type Tok struct {
	Kind string
	Text string
	Line int
	Val  Value
}

func (t Tok) shown() string {
	switch t.Kind {
	case "nl":
		return "end of line"
	case "eof":
		return "end of input"
	case "str":
		return "a string"
	}
	return "'" + t.Text + "'"
}

var keywords = map[string]bool{"let": true, "fn": true, "if": true, "then": true, "else": true, "end": true, "while": true, "do": true, "for": true, "in": true,
	"return": true, "and": true, "or": true, "not": true, "true": true, "false": true, "nil": true, "emit": true, "handle": true, "with": true, "print": true}

// a newline directly after one of these tokens does not end a statement
var suppress = map[string]bool{"(": true, "[": true, ",": true, "=": true, "=>": true, "then": true, "else": true, "do": true, "with": true, "in": true, "and": true, "or": true,
	"not": true, "+": true, "-": true, "*": true, "/": true, "%": true, "==": true, "!=": true, "<": true, "<=": true, ">": true, ">=": true, "|>": true}

const maxInt = int64(9223372036854775807)

func isDigit(c byte) bool { return c >= '0' && c <= '9' }
func isAlpha(c byte) bool { return (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || c == '_' }

func twoOp(s string) bool {
	switch s {
	case "==", "!=", "<=", ">=", "=>":
		return true
	case "|>":
		return PIPE
	}
	return false
}

func lex(src string) []Tok {
	if DEFER {
		keywords["defer"] = true
	}
	var toks []Tok
	i, n, line, depth := 0, len(src), 1, 0
	add := func(kind, text string, val Value) {
		toks = append(toks, Tok{Kind: kind, Text: text, Line: line, Val: val})
	}
	for i < n {
		c := src[i]
		switch {
		case c == '\n':
			if depth == 0 && len(toks) > 0 && toks[len(toks)-1].Kind != "nl" {
				last := toks[len(toks)-1]
				if !((last.Kind == "op" || last.Kind == "kw") && suppress[last.Text]) {
					add("nl", "\n", nil)
				}
			}
			line++
			i++
		case c == ' ' || c == '\t' || c == '\r':
			i++
		case c == '#':
			for i < n && src[i] != '\n' {
				i++
			}
		case isDigit(c):
			j := i
			for j < n && isDigit(src[j]) {
				j++
			}
			v, err := strconv.ParseInt(src[i:j], 10, 64)
			if err != nil {
				fail(line, "integer too large")
			}
			add("int", src[i:j], v)
			i = j
		case c == '"':
			j := i + 1
			var buf []byte
			for {
				if j >= n || src[j] == '\n' {
					fail(line, "unterminated string")
				}
				ch := src[j]
				if ch == '"' {
					break
				}
				if ch == '\\' {
					if j+1 >= n {
						fail(line, "bad escape")
					}
					switch src[j+1] {
					case 'n':
						buf = append(buf, '\n')
					case 't':
						buf = append(buf, '\t')
					case 'r':
						buf = append(buf, '\r')
					case '"':
						buf = append(buf, '"')
					case '\\':
						buf = append(buf, '\\')
					default:
						fail(line, "bad escape")
					}
					j += 2
				} else {
					buf = append(buf, ch)
					j++
				}
			}
			add("str", src[i:j+1], string(buf))
			i = j + 1
		case isAlpha(c):
			j := i
			for j < n && (isAlpha(src[j]) || isDigit(src[j])) {
				j++
			}
			w := src[i:j]
			if keywords[w] {
				add("kw", w, nil)
			} else {
				add("id", w, nil)
			}
			i = j
		case i+1 < n && twoOp(src[i:i+2]):
			add("op", src[i:i+2], nil)
			i += 2
		case c == '+' || c == '-' || c == '*' || c == '/' || c == '%' || c == '<' || c == '>' || c == '=' || c == '(' || c == ')' || c == '[' || c == ']' || c == ',' || c == ';':
			if c == '(' || c == '[' {
				depth++
			} else if (c == ')' || c == ']') && depth > 0 {
				depth--
			}
			add("op", string(c), nil)
			i++
		default:
			fail(line, fmt.Sprintf("bad character '%c'", c))
		}
	}
	add("eof", "", nil)
	return toks
}

solution.main.go:
// fable: runs a program of the Fable language read from standard input.
package main

import (
	"bufio"
	"fmt"
	"io"
	"os"
)

func run(src string) (out []string, status int) {
	it := newInterp()
	defer func() {
		if r := recover(); r != nil {
			e, ok := r.(*FableError)
			if !ok {
				panic(r)
			}
			out = append(it.out, fmt.Sprintf("error: line %d: %s", e.Line, e.Msg))
			status = 1
		}
	}()
	ast := (&Parser{toks: lex(src)}).program()
	it.runBlock(ast, it.globals, false)
	return it.out, 0
}

func main() {
	data, _ := io.ReadAll(bufio.NewReader(os.Stdin))
	out, status := run(string(data))
	w := bufio.NewWriter(os.Stdout)
	for _, l := range out {
		w.WriteString(l + "\n")
	}
	w.Flush()
	os.Exit(status)
}

solution.parser.go:
package main

// Node is an AST node; which fields are used depends on Kind.
type Node struct {
	Kind    string
	Line    int
	Name    string
	Val     Value
	A, B    *Node
	List    []*Node
	Params  []string
	Body    []*Node
	Else    []*Node
	HasElse bool
}

type Parser struct {
	toks []Tok
	i    int
}

func (p *Parser) peek(k int) Tok {
	j := p.i + k
	if j >= len(p.toks) {
		j = len(p.toks) - 1
	}
	return p.toks[j]
}

func (p *Parser) next() Tok {
	t := p.toks[p.i]
	if t.Kind != "eof" {
		p.i++
	}
	return t
}

func (p *Parser) bad(t Tok) { fail(t.Line, "unexpected "+t.shown()) }

func (p *Parser) isOp(text string, k int) bool {
	t := p.peek(k)
	return t.Kind == "op" && t.Text == text
}

func (p *Parser) isKw(text string, k int) bool {
	t := p.peek(k)
	return t.Kind == "kw" && t.Text == text
}

func (p *Parser) expectOp(text string) Tok {
	t := p.next()
	if !(t.Kind == "op" && t.Text == text) {
		p.bad(t)
	}
	return t
}

func (p *Parser) expectKw(text string) Tok {
	t := p.next()
	if !(t.Kind == "kw" && t.Text == text) {
		p.bad(t)
	}
	return t
}

func (p *Parser) expectID() Tok {
	t := p.next()
	if t.Kind != "id" {
		p.bad(t)
	}
	return t
}

func (p *Parser) atSep() bool {
	t := p.peek(0)
	return t.Kind == "nl" || (t.Kind == "op" && t.Text == ";")
}

func (p *Parser) atEnd(stops ...string) bool {
	t := p.peek(0)
	if t.Kind == "eof" {
		return true
	}
	if t.Kind == "kw" {
		for _, s := range stops {
			if t.Text == s {
				return true
			}
		}
	}
	return false
}

func (p *Parser) block(stops ...string) []*Node {
	var stmts []*Node
	for {
		for p.atSep() {
			p.next()
		}
		if p.atEnd(stops...) {
			return stmts
		}
		stmts = append(stmts, p.statement())
		if !(p.atSep() || p.atEnd(stops...)) {
			p.bad(p.peek(0))
		}
	}
}

func (p *Parser) program() []*Node {
	stmts := p.block()
	if t := p.peek(0); t.Kind != "eof" {
		p.bad(t)
	}
	return stmts
}

func (p *Parser) statement() *Node {
	t := p.peek(0)
	if t.Kind == "kw" {
		switch t.Text {
		case "let":
			p.next()
			name := p.expectID()
			p.expectOp("=")
			return &Node{Kind: "let", Line: t.Line, Name: name.Text, A: p.expr()}
		case "fn":
			if p.peek(1).Kind == "id" {
				p.next()
				name := p.next()
				params, body := p.fnRest()
				return &Node{Kind: "fndef", Line: t.Line, Name: name.Text, Params: params, A: body}
			}
		case "print":
			p.next()
			return &Node{Kind: "print", Line: t.Line, A: p.expr()}
		case "return":
			p.next()
			if p.atSep() || p.atEnd("end", "else") {
				return &Node{Kind: "return", Line: t.Line}
			}
			return &Node{Kind: "return", Line: t.Line, A: p.expr()}
		case "while":
			p.next()
			cond := p.expr()
			p.expectKw("do")
			body := p.block("end")
			p.expectKw("end")
			return &Node{Kind: "while", Line: t.Line, A: cond, Body: body}
		case "for":
			p.next()
			v := p.expectID()
			p.expectKw("in")
			seq := p.expr()
			p.expectKw("do")
			body := p.block("end")
			p.expectKw("end")
			return &Node{Kind: "for", Line: t.Line, Name: v.Text, A: seq, Body: body}
		case "defer":
			p.next()
			return &Node{Kind: "defer", Line: t.Line, A: p.statement()}
		}
	}
	if t.Kind == "id" && p.isOp("=", 1) {
		p.next()
		p.next()
		return &Node{Kind: "assign", Line: t.Line, Name: t.Text, A: p.expr()}
	}
	return &Node{Kind: "expr", Line: t.Line, A: p.expr()}
}

func (p *Parser) fnRest() ([]string, *Node) {
	p.expectOp("(")
	var params []string
	if !p.isOp(")", 0) {
		params = append(params, p.expectID().Text)
		for p.isOp(",", 0) {
			p.next()
			params = append(params, p.expectID().Text)
		}
	}
	p.expectOp(")")
	p.expectOp("=>")
	return params, p.expr()
}

func (p *Parser) expr() *Node {
	left := p.or()
	for PIPE && p.isOp("|>", 0) {
		op := p.next()
		right := p.postfix()
		left = &Node{Kind: "pipe", Line: op.Line, A: left, B: right}
	}
	return left
}

func (p *Parser) or() *Node {
	left := p.and()
	for p.isKw("or", 0) {
		t := p.next()
		left = &Node{Kind: "or", Line: t.Line, A: left, B: p.and()}
	}
	return left
}

func (p *Parser) and() *Node {
	left := p.not()
	for p.isKw("and", 0) {
		t := p.next()
		left = &Node{Kind: "and", Line: t.Line, A: left, B: p.not()}
	}
	return left
}

func (p *Parser) not() *Node {
	if p.isKw("not", 0) {
		t := p.next()
		return &Node{Kind: "not", Line: t.Line, A: p.not()}
	}
	return p.cmp()
}

func (p *Parser) cmp() *Node {
	left := p.add()
	t := p.peek(0)
	if t.Kind == "op" {
		switch t.Text {
		case "==", "!=", "<", "<=", ">", ">=":
			p.next()
			return &Node{Kind: "bin", Line: t.Line, Name: t.Text, A: left, B: p.add()}
		}
	}
	return left
}

func (p *Parser) add() *Node {
	left := p.mul()
	for {
		t := p.peek(0)
		if t.Kind == "op" && (t.Text == "+" || t.Text == "-") {
			p.next()
			left = &Node{Kind: "bin", Line: t.Line, Name: t.Text, A: left, B: p.mul()}
		} else {
			return left
		}
	}
}

func (p *Parser) mul() *Node {
	left := p.unary()
	for {
		t := p.peek(0)
		if t.Kind == "op" && (t.Text == "*" || t.Text == "/" || t.Text == "%") {
			p.next()
			left = &Node{Kind: "bin", Line: t.Line, Name: t.Text, A: left, B: p.unary()}
		} else {
			return left
		}
	}
}

func (p *Parser) unary() *Node {
	if p.isOp("-", 0) {
		t := p.next()
		return &Node{Kind: "neg", Line: t.Line, A: p.unary()}
	}
	return p.postfix()
}

func (p *Parser) postfix() *Node {
	e := p.primary()
	for {
		if p.isOp("(", 0) {
			t := p.next()
			var args []*Node
			if !p.isOp(")", 0) {
				args = append(args, p.expr())
				for p.isOp(",", 0) {
					p.next()
					args = append(args, p.expr())
				}
			}
			p.expectOp(")")
			e = &Node{Kind: "call", Line: t.Line, A: e, List: args}
		} else if p.isOp("[", 0) {
			t := p.next()
			idx := p.expr()
			p.expectOp("]")
			e = &Node{Kind: "index", Line: t.Line, A: e, B: idx}
		} else {
			return e
		}
	}
}

func (p *Parser) primary() *Node {
	t := p.next()
	switch t.Kind {
	case "int", "str":
		return &Node{Kind: "lit", Line: t.Line, Val: t.Val}
	case "id":
		return &Node{Kind: "var", Line: t.Line, Name: t.Text}
	case "kw":
		switch t.Text {
		case "true":
			return &Node{Kind: "lit", Line: t.Line, Val: true}
		case "false":
			return &Node{Kind: "lit", Line: t.Line, Val: false}
		case "nil":
			return &Node{Kind: "lit", Line: t.Line, Val: nil}
		case "fn":
			params, body := p.fnRest()
			return &Node{Kind: "lambda", Line: t.Line, Params: params, A: body}
		case "if":
			cond := p.expr()
			p.expectKw("then")
			a := p.block("else", "end")
			n := &Node{Kind: "if", Line: t.Line, A: cond, Body: a}
			if p.isKw("else", 0) {
				p.next()
				n.Else = p.block("end")
				n.HasElse = true
			}
			p.expectKw("end")
			return n
		case "do":
			body := p.block("end")
			p.expectKw("end")
			return &Node{Kind: "do", Line: t.Line, Body: body}
		case "handle":
			tag := p.expectID()
			p.expectKw("with")
			h := p.expr()
			p.expectKw("in")
			body := p.block("end")
			p.expectKw("end")
			return &Node{Kind: "handle", Line: t.Line, Name: tag.Text, A: h, Body: body}
		case "emit":
			tag := p.expectID()
			return &Node{Kind: "emit", Line: t.Line, Name: tag.Text, A: p.expr()}
		}
	case "op":
		if t.Text == "(" {
			e := p.expr()
			p.expectOp(")")
			return e
		}
		if t.Text == "[" {
			var items []*Node
			if !p.isOp("]", 0) {
				items = append(items, p.expr())
				for p.isOp(",", 0) {
					p.next()
					items = append(items, p.expr())
				}
			}
			p.expectOp("]")
			return &Node{Kind: "list", Line: t.Line, List: items}
		}
	}
	p.bad(t)
	return nil
}

