        t = self.next()
        k = t.kind
        if k == "int" or k == "str":
            return ("lit", t.line, t.value)
        if k == "id":
            return ("var", t.line, t.text)
        if k == "kw":
            w = t.text
            if w == "true":
                return ("lit", t.line, True)
            if w == "false":
                return ("lit", t.line, False)
            if w == "nil":
                return ("lit", t.line, None)
            if w == "fn":
                params, body = self.fn_rest()
                return ("lambda", t.line, params, body)
            if w == "if":
                cond = self.expr()
                self.expect_kw("then")
                a = self.block(("else", "end"))
                b = None
                if self.is_kw("else"):
                    self.next()
                    b = self.block(("end",))
                self.expect_kw("end")
                return ("if", t.line, cond, a, b)
            if w == "do":
                body = self.block(("end",))
                self.expect_kw("end")
                return ("do", t.line, body)
            if w == "handle":
                tag = self.expect_id()
                self.expect_kw("with")
                h = self.expr()
                self.expect_kw("in")
                body = self.block(("end",))
                self.expect_kw("end")
                return ("handle", t.line, tag.text, h, body)
            if w == "emit":
                tag = self.expect_id()
                return ("emit", t.line, tag.text, self.expr())
        if k == "op":
            if t.text == "(":
                e = self.expr()
                self.expect_op(")")
                return e
            if t.text == "[":
                items = []
                if not self.is_op("]"):
                    items.append(self.expr())
                    while self.is_op(","):
                        self.next()
                        items.append(self.expr())
                self.expect_op("]")
                return ("list", t.line, items)
        self.bad(t)

